export const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export function decimal(v){if(v==='')return null;if(!/^\d+(?:[.,]\d{0,2})?$/.test(v)||Number(v.replace(',','.'))>2000)throw Error('Use uma carga entre 0 e 2000 kg, com até duas casas.');return Number(v.replace(',','.'));}
export function generate(profile,library,month){let available=library.filter(e=>profile.equipment.includes(e.equipment)&&e.level<=(profile.level==='iniciante'?1:2));let groups=['peito','costas','pernas','posteriores','ombros','bíceps','tríceps','panturrilhas'];if(!['peito','costas','pernas','posteriores'].every(g=>available.some(e=>e.group===g)))throw Error('Os equipamentos selecionados não cobrem o corpo todo nesta biblioteca. Inclua máquinas e polia ou halteres, barra e polia. Não foi gerado um plano incompleto.');const days=profile.days.map(Number).sort((a,b)=>a-b);if(days.length!==Number(profile.frequency))throw Error('Selecione exatamente a quantidade de dias informada.');let split=days.length<=3?'Corpo inteiro':days.length===4?'Superior / Inferior':'Empurrar / Puxar / Pernas';if(days.length<=3&&days.some(d=>days.includes((d+1)%7)))throw Error('Para este plano de corpo inteiro, escolha dias intercalados para recuperação.');let templates=days.map((day,i)=>{let gs=days.length<=3?[...groups]:days.length===4?(i%2===0?['peito','costas','ombros','bíceps','tríceps']:['pernas','posteriores','glúteos','panturrilhas']):[['peito','ombros','tríceps'],['costas','bíceps','ombros'],['pernas','posteriores','panturrilhas']][i%3];let count=Number(profile.minutes)<=30?4:Number(profile.minutes)<=45?5:6;let chosen=gs.map(g=>available.find(e=>e.group===g)).filter(Boolean);if(days.length>3)chosen.push(...available.filter(e=>gs.includes(e.group)&&!chosen.some(c=>c.id===e.id)));chosen=chosen.slice(0,count);return {day,name:days.length<=3?'Corpo inteiro '+String.fromCharCode(65+i):days.length===4?(i%2?'Inferior':'Superior')+' '+(Math.floor(i/2)+1):['Empurrar','Puxar','Pernas'][i%3],exercises:chosen.map(e=>({exerciseId:e.id,sets:profile.level==='iniciante'?2:3,reps:profile.goal==='força'?'6–8':profile.goal==='condicionamento'?'12–15':'8–12',rest:profile.goal==='força'?120:75,warmup:['peito','costas','pernas','posteriores'].includes(e.group)}))}});let dates={};let [y,m]=month.split('-').map(Number);for(let d=new Date(y,m-1,1,12);d.getMonth()===m-1;d.setDate(d.getDate()+1)){let t=templates.find(t=>t.day===d.getDay());if(t)dates[localDate(d)]=JSON.parse(JSON.stringify(t));}return {id:typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''),month,created:Date.now(),profile:structuredClone(profile),split,dates};}
export function validateBackup(x,library){if(!x||x.version!==1||!Array.isArray(x.plans)||!x.sessions||typeof x.sessions!=='object'||Array.isArray(x.sessions))throw Error('Formato de backup inválido.');if(x.plans.length>120)throw Error('Backup grande demais.');if(x.currentPlan!==null&&x.currentPlan!==undefined&&!x.plans.some(p=>p.id===x.currentPlan))throw Error('Plano selecionado inexistente.');let ids=new Set(library.map(e=>e.id));for(let p of x.plans){if(typeof p.id!=='string'||!/^\d{4}-\d{2}$/.test(p.month)||!p.dates)throw Error('Plano inválido.');for(let [date,t] of Object.entries(p.dates)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Array.isArray(t.exercises))throw Error('Sessão inválida.');for(let e of t.exercises)if(!ids.has(e.exerciseId)||!Number.isInteger(e.sets)||e.sets<1||e.sets>10||typeof e.reps!=='string'||e.reps.length>30||!Number.isFinite(e.rest)||e.rest<0||e.rest>600)throw Error('Exercício inválido.');}}for(let s of Object.values(x.sessions)){if(!s||!Array.isArray(s.exercises)||typeof s.date!=='string'||typeof s.planId!=='string')throw Error('Registro inválido.');for(let e of s.exercises){if(!ids.has(e.exerciseId)||!Array.isArray(e.loads)||e.loads.some(l=>l!==null&&(!Number.isFinite(l)||l<0||l>2000))||!(e.load===null||Number.isFinite(e.load)&&e.load>=0&&e.load<=2000))throw Error('Carga inválida.');}}if(x.profile){let p=x.profile;if(!['hipertrofia','força','condicionamento'].includes(p.goal)||!['iniciante','intermediário','avançado'].includes(p.level)||!Array.isArray(p.days)||p.days.length!==Number(p.frequency)||p.days.some(d=>!Number.isInteger(Number(d))||d<0||d>6)||!Array.isArray(p.equipment)||typeof p.restrictions!=='string')throw Error('Perfil inválido.');}return x;}
